// One-time clean slate explicitly requested by the Site owner on 2026-10-04.
// The durable marker prevents subsequent visits from deleting newly saved data.
const REQUESTED_RESET_OWNER="snrd86ZY2iZCt2ce4Lp8sXsvJePXzSUjinOgrswcoZy42BHK57YrmZ";
const REQUESTED_RESET_KEY='clean-slate-2026-10-04T17:03:12Z';
const RESET_TABLES=['fighter_growth','fighter_growth_sync','match_records','match_record_sync','champion_history','current_champions','saved_tournaments','tournament_name_claims','roster_archives','saved_characters','roster_refreshes'];
async function applyRequestedReset(env){
 const db=env.DB;
 const done=await db.prepare('SELECT 1 AS done FROM roster_refreshes WHERE owner_id = ? AND batch_key = ?').bind(REQUESTED_RESET_OWNER,REQUESTED_RESET_KEY).first();
 if(done)return;
 const guard='NOT EXISTS (SELECT 1 FROM roster_refreshes WHERE owner_id = ? AND batch_key = ?)';
 const statements=RESET_TABLES.map(table=>db.prepare('DELETE FROM '+table+' WHERE owner_id = ? AND '+guard).bind(REQUESTED_RESET_OWNER,REQUESTED_RESET_OWNER,REQUESTED_RESET_KEY));
 statements.push(db.prepare('INSERT OR IGNORE INTO roster_refreshes (owner_id,batch_key,nonce,template_json,result_json,created_at) VALUES (?,?,?,?,?,?)').bind(REQUESTED_RESET_OWNER,REQUESTED_RESET_KEY,'completed','{}','{"cleanSlate":true}',Date.now()));
 await db.batch(statements);
}

// Names belong to tournament IDs, so simultaneous initial saves reuse a claim.
async function claimTournamentName(env,owner,id,requested){
 for(let attempt=0;attempt<10;attempt++){
  const existing=await env.DB.prepare('SELECT name,display_name FROM tournament_name_claims WHERE owner_id = ? AND tournament_id = ?').bind(owner,id).first();
  if(existing)return existing.display_name||existing.name;
  const used=await env.DB.prepare('SELECT name FROM saved_tournaments WHERE owner_id = ? UNION SELECT tournament_name AS name FROM champion_history WHERE owner_id = ? UNION SELECT name FROM tournament_name_claims WHERE owner_id = ?').bind(owner,owner,owner).all();
  const name=uniqueTournamentName(requested,used.results.map(row=>row.name));
  const claimed=await env.DB.prepare('INSERT INTO tournament_name_claims (owner_id, name, tournament_id, display_name) VALUES (?, ?, ?, ?) ON CONFLICT DO NOTHING RETURNING name').bind(owner,name.toLowerCase(),id,name).first();
  if(claimed)return name;
 }
 const retry=await env.DB.prepare('SELECT name,display_name FROM tournament_name_claims WHERE owner_id = ? AND tournament_id = ?').bind(owner,id).first();
 if(retry)return retry.display_name||retry.name;
 fail('Another tournament is reserving this name. Please try again.',409);
}

// Repair the three cups affected after the owner's clean slate. No results,
// fighters, timestamps or championship counts are removed.
const NAME_REPAIR_OWNER='snrd86ZY2iZCt2ce4Lp8sXsvJePXzSUjinOgrswcoZy42BHK57YrmZ';
const NAME_REPAIR_KEY='clean-slate-name-repair-2026-10-04';
const NAME_REPAIRS=[['2ac538f4-52ff-4443-aa8a-ec2a357c6241','Moonfall Clash'],['341363f7-aa09-4aed-ac60-320e1dfb7560','Thunderforge Gauntlet'],['d82c9c15-2b26-41ef-b0c8-8d17aecd3d99','Silver Tempest Grand Prix']];
async function repairRequestedTournamentNames(env){
 const db=env.DB,owner=NAME_REPAIR_OWNER,key=NAME_REPAIR_KEY;
 if(await db.prepare('SELECT 1 AS done FROM roster_refreshes WHERE owner_id = ? AND batch_key = ?').bind(owner,key).first())return;
 const statements=[],guard='NOT EXISTS (SELECT 1 FROM roster_refreshes WHERE owner_id = ? AND batch_key = ?)';
 for(const [id,name]of NAME_REPAIRS){
  const row=await db.prepare('SELECT name,state_json FROM saved_tournaments WHERE owner_id = ? AND id = ?').bind(owner,id).first();
  if(!row||row.name!==name+' 2')continue;
  const occupied=await db.prepare('SELECT 1 AS used FROM saved_tournaments WHERE owner_id = ? AND lower(name) = ? UNION SELECT 1 FROM champion_history WHERE owner_id = ? AND lower(tournament_name) = ?').bind(owner,name.toLowerCase(),owner,name.toLowerCase()).first();
  if(occupied)continue;
  const state=await decodeTournament(row.state_json);state.name=name;
  statements.push(db.prepare('UPDATE saved_tournaments SET name = ?, state_json = ? WHERE owner_id = ? AND id = ? AND name = ? AND '+guard).bind(name,await encodeTournament(state),owner,id,row.name,owner,key));
  for(const table of ['champion_history','current_champions'])statements.push(db.prepare('UPDATE '+table+' SET tournament_name = ? WHERE owner_id = ? AND tournament_id = ? AND tournament_name = ? AND '+guard).bind(name,owner,id,row.name,owner,key));
 }
 // Legacy reservations without any surviving cup/history cannot affect names.
 statements.push(db.prepare('DELETE FROM tournament_name_claims WHERE owner_id = ? AND tournament_id IS NULL AND lower(name) NOT IN (SELECT lower(name) FROM saved_tournaments WHERE owner_id = ? UNION SELECT lower(tournament_name) FROM champion_history WHERE owner_id = ?) AND '+guard).bind(owner,owner,owner,owner,key));
 statements.push(db.prepare('UPDATE tournament_name_claims SET tournament_id = (SELECT id FROM saved_tournaments WHERE owner_id = ? AND lower(name) = tournament_name_claims.name LIMIT 1) WHERE owner_id = ? AND tournament_id IS NULL AND '+guard).bind(owner,owner,owner,key));
 statements.push(db.prepare('INSERT OR IGNORE INTO tournament_name_claims (owner_id,name,tournament_id,display_name) SELECT owner_id,lower(name),id,name FROM saved_tournaments WHERE owner_id = ? AND '+guard).bind(owner,owner,key));
 statements.push(db.prepare('INSERT OR IGNORE INTO roster_refreshes (owner_id,batch_key,nonce,template_json,result_json,created_at) VALUES (?,?,?,?,?,?)').bind(owner,key,'completed','{}','{"tournamentNamesRepaired":true}',Date.now()));
 await db.batch(statements);
}

const ARENA_THEMES=['Ashen Crown','Moonfall','Iron Fang','Crimson Eclipse','Stormbound','Obsidian Gate','Celestial Rift','Frostfire','Twilight Blade','Dragonheart','Silver Tempest','Emerald Throne','Voidborn','Emberfall','Wild Hunt','Crystal Dawn','Thunderforge','Shadowspire','Golden Phoenix','Runestone','Bloodmoon','Starfall','Winter Warden','Shattered Realm'];
const ARENA_EVENTS=['Cup','Clash','Championship','Trials','Tournament','Grand Prix','Gauntlet','Open'];
function uniqueTournamentName(requested,usedNames=[]){
 const used=new Set(usedNames.map(name=>name.trim().toLowerCase()));let base=requested.trim()||'Fateforge Cup';
 if(!used.has(base.toLowerCase()))return base;
 const numbered=/^(.*) (\d+)$/.exec(base);if(numbered&&used.has(numbered[1].toLowerCase()))base=numbered[1];
 for(let n=2;;n++){const suffix=' '+n,candidate=base.slice(0,100-suffix.length)+suffix;if(!used.has(candidate.toLowerCase()))return candidate;}
}
function randomTournamentName(usedNames=[],randomIndex=n=>{const a=new Uint32Array(1),limit=Math.floor(4294967296/n)*n;do{crypto.getRandomValues(a);}while(a[0]>=limit);return a[0]%n;}){
 return uniqueTournamentName(ARENA_THEMES[randomIndex(ARENA_THEMES.length)]+' '+ARENA_EVENTS[randomIndex(ARENA_EVENTS.length)],usedNames);
}

function summarizeChampionHistory(history){
 const ordered=[...history].sort((a,b)=>a.completedAt-b.completedAt||a.tournamentId.localeCompare(b.tournamentId));
 const cups=new Map(),records=new Map();
 for(const event of ordered){
  let cup=cups.get(event.divisionKey);if(!cup){cup={divisionKey:event.divisionKey,label:event.label,total:0,lastWinner:null,streak:0};cups.set(event.divisionKey,cup);}
  cup.total++;cup.streak=cup.lastWinner===event.characterId?cup.streak+1:1;cup.lastWinner=event.characterId;cup.lastTournamentId=event.tournamentId;
  const key=event.divisionKey+'|'+event.characterId;let record=records.get(key);
  if(!record){record={divisionKey:event.divisionKey,label:event.label,characterId:event.characterId,characterName:event.characterName,titles:0,currentStreak:0,bestStreak:0,lastWonAt:0};records.set(key,record);}
  record.characterName=event.characterName;record.titles++;record.bestStreak=Math.max(record.bestStreak,cup.streak);record.lastWonAt=event.completedAt;
 }
 for(const record of records.values()){const cup=cups.get(record.divisionKey);record.currentStreak=cup.lastWinner===record.characterId?cup.streak:0;}
 return {records:[...records.values()].sort((a,b)=>b.titles-a.titles||b.lastWonAt-a.lastWonAt||a.characterId.localeCompare(b.characterId)),divisions:[...cups.values()].sort((a,b)=>a.label.localeCompare(b.label))};
}

// New series stop at the first majority; legacy recordings retain their original length.
const validBestOf=n=>[1,3,5].includes(n);
const seriesComplete=(format,score,games,knockout=false)=>format.bestOf!==undefined?Math.max(...score)>=Math.floor(format.bestOf/2)+1||format.allowDraw&&!knockout&&games>=format.bestOf:games>=format.legs&&(!knockout||score[0]!==score[1]);
// Keep the combat engine and old replays intact; competition rules decide
// whether an otherwise adjudicated time-limit result is a draw.
const drawAtTimeLimit=(result,allowDraw)=>allowDraw&&result.reason?.startsWith('Time limit:')?{...result,winner:null,reason:'Time limit: draw'}:result;
const seriesLabel=format=>format.bestOf!==undefined?`Bo${format.bestOf}`:`Legacy series · ${format.legs} games`;
function assertSeriesResult(format,results,a,b,knockout=false){
 const score=[0,0];if(!results.length)throw new Error('Finish the match series.');
 for(const [index,result]of results.entries()){if(result.winner!==a&&result.winner!==b&&!(format.allowDraw&&!knockout&&result.winner===null&&result.seconds>=90))throw new Error('Invalid game winner.');if(format.bestOf!==undefined&&seriesComplete(format,score,index,knockout))throw new Error('The series already ended.');if(result.winner!==null)score[result.winner===a?0:1]++;}
 if(!seriesComplete(format,score,results.length,knockout))throw new Error('Finish the match series.');
 return score;
}

const PROMOTION_WINS={E:1,D:1,C:2,B:4,A:8,S:16};
