 const titles=[];
 if(played.some(m=>m.phase==='league')&&world.phase!=='league')for(let d=0;d<7;d++)titles.push({key:`league:${d}`,label:LEAGUES.names[d]+' league',champion:LEAGUES.standings(world,d)[0].id});
