// Core siege engines: team-3-core, team-3 … team-3.9, and team-4.0 onwards.
const isObjectiveEngine=version=>/^team-(3|[4-9]|\d{2,})(\.|-|$)/.test(version??'');
const engineForMode=battleMode=>battleMode==='core'?OBJECTIVE_COMBAT_VERSION:TEAM_COMBAT_VERSION;
// Engines whose matches carry coach game plans.
const GAME_PLAN_ENGINES=Object.freeze(['team-3.6','team-3.7','team-3.8','team-3.9','team-4.0']);

// Core siege game plan: three coach dials that steer the team brain (team-3.6). Shared by the engine, the league
// rules, the worker and the UI. AI coaches take their dials from their personality and adjust one after a loss.
const GAME_PLAN_OPTIONS=Object.freeze({
 titan:Object.freeze([['always','Always contest'],['ahead','Contest when ahead'],['never','Never (play around it)']]),
 style:Object.freeze([['group','Group up'],['flank','Flank']]),
 siege:Object.freeze([['forgefire','With Forgefire'],['numbers','On a numbers lead'],['late','Not before 3:00']]),
 // Ember Wisps (level-combat.js, team-4.0): when a few fighters may take a wisp for XP. Optional; plans without it
 // take wisps when the team is not ahead in levels.
 camp:Object.freeze([['behind','When not ahead in levels'],['always','Always'],['never','Never']])
});
const GAME_PLAN_LABELS=Object.freeze({titan:'Titan priority',style:'Style',siege:'Siege timing',camp:'Ember Wisps'});
const DIALS=Object.keys(GAME_PLAN_OPTIONS),REQUIRED=Object.freeze(['titan','style','siege']);
function validGamePlan(plan){return !!plan&&typeof plan==='object'&&!Array.isArray(plan)&&Object.keys(plan).every(k=>DIALS.includes(k))&&REQUIRED.every(k=>k in plan)&&Object.keys(plan).every(k=>GAME_PLAN_OPTIONS[k].some(([v])=>v===plan[k]));}
const plan=(titan,style,siege)=>Object.freeze({titan,style,siege});
// Coach personalities (team-league.js PERSONALITIES) and the tactics they map to.
const PERSONALITY_PLANS=Object.freeze({
 balanced:plan('always','group','numbers'),
 fortress:plan('ahead','group','numbers'),
 glass:plan('always','group','numbers'),
 tactician:plan('ahead','flank','numbers'),
 star:plan('always','group','numbers'),
 bargain:plan('never','flank','numbers')
});
const TACTIC_PERSONALITY=Object.freeze({balanced:'balanced',defensive:'fortress',aggressive:'glass','focus-healer':'tactician','protect-carry':'star'});
function defaultGamePlan(tactic){return {...PERSONALITY_PLANS[TACTIC_PERSONALITY[tactic]??'balanced']};}
// League coaches' Ember Wisp dial by personality.
const PERSONALITY_CAMP=Object.freeze({balanced:'behind',fortress:'behind',glass:'never',tactician:'always',star:'behind',bargain:'always'});
function personalityGamePlan(personality){return {...(PERSONALITY_PLANS[personality]??PERSONALITY_PLANS.balanced),camp:PERSONALITY_CAMP[personality]??'behind'};}
// After a loss an AI coach changes one dial, chosen by personality; winners keep their plan. Deterministic.
const ADAPT=Object.freeze({balanced:'titan',fortress:'siege',glass:'style',tactician:'style',star:'siege',bargain:'titan'});
const NEXT=Object.freeze({titan:{always:'ahead',ahead:'always',never:'ahead'},style:{group:'flank',flank:'group'},siege:{forgefire:'numbers',numbers:'forgefire',late:'numbers'}});
function adaptGamePlan(current,personality,lost){if(!lost)return {...current};const dial=ADAPT[personality]??'titan';return {...current,[dial]:NEXT[dial][current[dial]]};}
function gamePlanSummary(p){return DIALS.filter(k=>p[k]!=null).map(k=>GAME_PLAN_OPTIONS[k].find(([v])=>v===p[k])?.[1]).join(' · ');}

// Team battle fields: a 960×600 arena with optional terrain. Every map is mirrored across the centre line,
// so neither side gains ground, and terrain stays out of both spawn zones (x < 280 and x > 680).
const TEAM_FIELD=Object.freeze({width:960,height:600});
const TEAM_MAPS=Object.freeze([
 Object.freeze({id:'open',label:'Open field',weight:4}),
 Object.freeze({id:'pillars',label:'Pillar hall',weight:1.5}),
 Object.freeze({id:'ruins',label:'Broken ruins',weight:1.5}),
 Object.freeze({id:'crossroads',label:'Crossroads',weight:1.5}),
 Object.freeze({id:'groves',label:'Stone groves',weight:1.5})
]);
const MAP_IDS=Object.freeze(TEAM_MAPS.map(m=>m.id));
const mapLabel=id=>TEAM_MAPS.find(m=>m.id===id)?.label??'Open field';
function random(seed){let a=seed>>>0;return()=>{a=(a+0x6D2B79F5)>>>0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
// 'random' picks by weight from the battle seed with its own salt, so time, weather and ground rolls are unchanged.
function resolveMap(seed,choice='random'){
 if(MAP_IDS.includes(choice))return choice;
 const total=TEAM_MAPS.reduce((n,m)=>n+m.weight,0);let roll=random((seed^0x5bd1e995)>>>0)()*total;
 for(const m of TEAM_MAPS){roll-=m.weight;if(roll<0)return m.id;}return 'open';
}
// Terrain pieces are circles (the engine's obstacle shape). Pieces either touch (walls are chains of circles)
// or leave at least a 40-unit gap, so fighters never wedge between two rocks.
function mapTerrain(id,seed){
 const r=random((seed^0x2c1b3c6d)>>>0),j=n=>(r()-.5)*2*n,pieces=[],{width,height}=TEAM_FIELD,mid=width/2;
 const add=(x,y,radius)=>{pieces.push({x,y,radius});if(Math.abs(x-mid)>1)pieces.push({x:width-x,y,radius});};
 if(id==='pillars'){for(const y of [150,450])add(340+j(20),y+j(25),22+r()*6);if(r()<.5)add(mid,height/2+j(40),26);else{add(mid,95+j(15),18);add(mid,505+j(15),18);}}
 else if(id==='ruins'){const x=372+j(10),gap=j(18);for(let y=86;y<=226;y+=28)add(x,y+gap,13);for(let y=374;y<=514;y+=28)add(x,y+gap,13);add(mid-42,height/2+j(10),15);}
 else if(id==='crossroads'){const y=height/2+j(12);add(mid,y,32);add(mid-72,y-82,16);add(mid-72,y+82,16);add(395+j(15),70+j(8),20);add(395+j(15),530+j(8),20);}
 else if(id==='groves'){const placed=[];for(let n=0;n<40&&placed.length<6;n++){const p={x:300+r()*138,y:60+r()*480,radius:10+r()*7};if(placed.every(q=>Math.hypot(q.x-p.x,q.y-p.y)>q.radius+p.radius+46)){placed.push(p);add(p.x,p.y,p.radius);}}}
 const round=v=>Math.round(v*10)/10;
 return pieces.map(p=>({x:round(p.x),y:round(p.y),radius:round(p.radius),life:Infinity,terrain:true}));
}

// Shared by the worker, watched games and the authoritative league validator.

const SERIES_TACTICS=['balanced','protect-carry','focus-healer','aggressive','defensive'];
function seriesScore(games=[]){return games.reduce((score,g)=>{score[g.winnerTeam]++;return score;},[0,0]);}
function seriesTactics(match,games=[]){
 const initial=match.initialTactics??match.tactics,previous=games.at(-1),score=seriesScore(games);
 if(!previous||match.seriesRulesVersion!==2)return [...initial];
 return initial.map((base,side)=>{
  const last=previous.tactics?.[side]??base;
  if(side===match.userSide||previous.winnerTeam===side)return last;
  const style=match.coachStyles?.[side]??'balanced',behind=score[side]<score[1-side];
  if(style==='glass')return 'aggressive';
  if(style==='fortress')return last==='defensive'?'protect-carry':'defensive';
  if(style==='tactician')return last==='focus-healer'?'balanced':'focus-healer';
  if(style==='star')return behind?'focus-healer':'protect-carry';
  if(style==='bargain')return behind?'aggressive':'balanced';
  return last==='balanced'?'protect-carry':'balanced';
 });
}
// Core siege game plans (team-3.6+): winners keep theirs, the user keeps theirs, AI losers adjust one dial.
function seriesGamePlans(match,games=[]){
 const initial=match.initialGamePlans??match.gamePlans;if(!initial)return null;const previous=games.at(-1);
 return initial.map((base,side)=>{const last=previous?.gamePlans?.[side]??base;return !previous||side===match.userSide||previous.winnerTeam===side?{...last}:adaptGamePlan(last,match.coachStyles?.[side],true);});
}
function seriesGameOptions(match,games=[],choice=null){
 const tactics=seriesTactics(match,games),lineups=(games.at(-1)?.lineups??match.initialLineups??match.lineups).map(ids=>[...ids]),gamePlans=seriesGamePlans(match,games);
 if(choice&&match.userSide>=0){if(choice.lineup)lineups[match.userSide]=[...choice.lineup];if(choice.tactic)tactics[match.userSide]=choice.tactic;if(choice.gamePlan&&gamePlans)gamePlans[match.userSide]={...choice.gamePlan};}
 return {lineups,tactics,...(gamePlans?{gamePlans}:{})};
}





