const CURRENT_CATALOG_REVISION="f1021888bd93ff3656f7f3d03ed5edc4bd170d9200d23ec032c2102806680f52";
const SHARED_POOL_ID='standard:'+GENERATION_POOL_REVISION;
function canonicalPools(pools){return JSON.stringify(pools,(key,value)=>value&&typeof value==='object'&&!Array.isArray(value)?Object.fromEntries(Object.keys(value).sort().map(k=>[k,value[k]])):value);}
const CANONICAL_GENERATION_POOLS=canonicalPools(GENERATION_POOLS);
async function findCharacterPool(env,pools,canonical){const exact=await env.DB.prepare('SELECT id FROM character_pools WHERE pools_json = ? LIMIT 1').bind(pools).first();if(exact)return exact;const rows=await env.DB.prepare('SELECT id,pools_json FROM character_pools').bind().all();return rows.results.find(row=>canonicalPools(JSON.parse(row.pools_json))===canonical);}
async function prepareSharedPool(env){const row=await findCharacterPool(env,JSON.stringify(GENERATION_POOLS),CANONICAL_GENERATION_POOLS);return row?.id||SHARED_POOL_ID;}
const sharedPoolStatement=(env,id=SHARED_POOL_ID)=>env.DB.prepare('INSERT INTO character_pools(id,pools_json) VALUES(?,?) ON CONFLICT(id) DO NOTHING').bind(id,JSON.stringify(GENERATION_POOLS));
function hydrateRow(row){if(!row)return row;const state=JSON.parse(row.state_json);if(!state.pools){if(!row.pools_json)fail('The saved fighter catalog is missing.',503);state.pools=JSON.parse(row.pools_json);return {...row,stored_state_json:row.state_json,state_json:JSON.stringify(state)};}return row;}
async function packCharacterSnapshot(env,state){
 const pools=JSON.stringify(state.pools),canonical=canonicalPools(state.pools),existing=await findCharacterPool(env,pools,canonical);
 const poolId=existing?.id||(canonical===CANONICAL_GENERATION_POOLS?SHARED_POOL_ID:'pool:'+Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(canonical))),v=>v.toString(16).padStart(2,'0')).join(''));
 await env.DB.prepare('INSERT INTO character_pools(id,pools_json) VALUES(?,?) ON CONFLICT(id) DO NOTHING').bind(poolId,pools).run();
 return {poolId,stateJson:JSON.stringify({...state,pools:undefined})};
}
async function saveCharacterSnapshot(env,owner,id,name,state,summary,now){
 const packed=await packCharacterSnapshot(env,state);
 return env.DB.prepare('INSERT INTO saved_characters(id,owner_id,name,state_json,summary_json,catalog_revision,created_at,updated_at,pool_id) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO NOTHING RETURNING id,name,summary_json,created_at,updated_at').bind(id,owner,name,packed.stateJson,JSON.stringify(summary),CURRENT_CATALOG_REVISION,now,now,packed.poolId).first();
}

const ASSET_VERSION="ffa8e0933c0844f1";
const traitSlots=['power','power2','weakness'];
const emptyPower=name=>/^no (second )?power$/i.test(String(name).trim());
function chooseReplacement(options,random=()=>crypto.getRandomValues(new Uint32Array(1))[0]/4294967296){
 if(!options.length)throw new Error('No replacement traits are available.');
 let ticket=random()*options.reduce((sum,o)=>sum+o.weight,0);
 for(const o of options){ticket-=o.weight;if(ticket<0)return o.name;}
 return options.at(-1).name;
}
// Saved official-name manifests distinguish retired game options from intentional custom options.
function reconcileCharacter(input,catalog,random){
 const state=structuredClone(input),repairs=[];
 const supported=o=>(state.generationVersion??1)>=4||!globalThis.SUPPORT_ABILITIES?.[o.name];
 const official={powers:catalog.power.filter(o=>supported(o)&&!emptyPower(o.name)&&((state.generationVersion??1)>=3||!globalThis.CLASS_ABILITIES?.newOptions.some(a=>a.name===o.name))).map(o=>o.name),weaknesses:catalog.weakness.map(o=>o.name)};
 const previous=state.catalog;
 for(const slot of traitSlots){
  // Historical fighters keep their spell-only catalog and cannot receive a new
  // technique while repairing a retired name under a pinned old combat engine.
  const list=catalog[slot].filter(o=>supported(o)&&(slot==='weakness'||(state.generationVersion??1)>=3||!globalThis.CLASS_ABILITIES?.newOptions.some(a=>a.name===o.name))),names=new Set(list.map(o=>o.name));
  const oldOfficial=previous?.[slot==='weakness'?'weaknesses':'powers'];
  const retired=name=>!names.has(name)&&!emptyPower(name)&&(!oldOfficial||oldOfficial.includes(name));
  state.pools.base[slot]=state.pools.base[slot].filter(o=>!retired(o.name));
  const selected=state.traits[slot];
  if(selected&&retired(selected)){
   const other=slot==='power'?'power2':'power';
   const eligible=list.filter(o=>supported(o)&&(slot==='weakness'||!emptyPower(o.name)&&o.name!==state.traits[other]));
   const replacement=chooseReplacement(eligible,random);
   if(!state.pools.base[slot].some(o=>o.name===replacement)){
    // A retired saved selection frees its slot, even in a deliberately restricted custom wheel.
    state.pools.base[slot].push(structuredClone(list.find(o=>o.name===replacement)));
   }
   state.traits[slot]=replacement;repairs.push({slot,from:selected,to:replacement});
  }
  for(const o of list)if((!previous||!emptyPower(o.name)&&!oldOfficial.includes(o.name))&&state.pools.base[slot].length<200&&!state.pools.base[slot].some(saved=>saved.name===o.name))state.pools.base[slot].push(structuredClone(o));
 }
 state.catalog={version:1,...official};
 return {state,repairs,changed:JSON.stringify(state)!==JSON.stringify(input)};
}

