const pruneReceipts=(env,table,owner)=>env.DB.prepare(`DELETE FROM ${table} WHERE owner_id = ? AND rowid NOT IN (SELECT rowid FROM ${table} WHERE owner_id = ? ORDER BY rowid DESC LIMIT ${RECEIPT_LIMIT})`).bind(owner,owner);
